/* ============ SOCRATES — question banks ============
   Every question here is original NaukriSala content, written for practice.
   Format: { q, s? (scenario), o: [4 options], a: correct index, w: why, d: 1|2|3 }
   d = difficulty: 1 Beginner, 2 Intermediate, 3 Advanced. */

const BANKS = {

'aml-kyc': [
{ q:'What are the three stages of money laundering, in order?', o:['Placement → Layering → Integration','Layering → Placement → Integration','Integration → Placement → Layering','Placement → Integration → Layering'], a:0, w:'Dirty money enters the system (placement), is moved around to hide its trail (layering), then re-enters as apparently clean money (integration).', d:1 },
{ q:'KYC stands for…', o:['Know Your Customer','Keep Your Cash','Know Your Country','Kernel Yield Calculation'], a:0, w:'KYC = Know Your Customer — verifying who a customer is before and during the relationship.', d:1 },
{ q:'What is the main purpose of Customer Due Diligence (CDD)?', o:['To sell the customer more products','To verify the customer’s identity and understand the nature of their activity','To check the customer’s credit score only','To set the customer’s interest rate'], a:1, w:'CDD identifies and verifies the customer and helps the institution understand expected activity, so unusual behaviour stands out.', d:1 },
{ q:'A PEP is a…', o:['Public Employment Permit','Politically Exposed Person','Personal Equity Plan','Priority Escalation Protocol'], a:1, w:'A Politically Exposed Person holds a prominent public function and carries higher corruption-related risk, so PEPs get enhanced scrutiny.', d:1 },
{ q:'At onboarding, an individual customer is typically asked for…', o:['Only a phone number','A government photo ID and proof of address','Their employer’s balance sheet','A reference letter from a celebrity'], a:1, w:'Standard KYC collects an officially valid photo ID plus address proof, verified against the originals or digital records.', d:1 },
{ q:'Sanctions screening means…', o:['Checking whether staff took unauthorised leave','Checking customer names against government and international sanctions lists','Approving loans above a limit','Auditing branch cash'], a:1, w:'Screening compares customer (and counterparty) names against lists such as OFAC, UN, EU and local lists, at onboarding and throughout the relationship.', d:1 },
{ q:'In India, an STR filed by a bank is a…', o:['Stock Transfer Receipt','Suspicious Transaction Report','Standard Tax Return','Service Ticket Request'], a:1, w:'STR = Suspicious Transaction Report, filed with FIU-IND when a transaction appears suspicious — regardless of its amount.', d:1 },
{ q:'STRs in India are filed with…', o:['The Reserve Bank of India','FIU-IND (Financial Intelligence Unit – India)','SEBI','The Income Tax Department directly'], a:1, w:'Banks and other reporting entities file STRs and CTRs with FIU-IND under the PMLA framework.', d:2 },
{ q:'Under India’s reporting rules, a Cash Transaction Report (CTR) covers…', o:['Every cash deposit','Cash transactions above ₹10 lakh (or a series that adds up within a month)','Only foreign-currency transactions','Cash withdrawals by staff'], a:1, w:'Cash transactions exceeding ₹10 lakh — including connected transactions in a month — are reported via CTR; suspicion, by contrast, is reported at any amount via STR.', d:2 },
{ q:'Enhanced Due Diligence (EDD) is applied when…', o:['A customer opens a savings account','The customer is assessed as high-risk — e.g. a PEP, high-risk geography, or complex ownership','The customer is a long-standing low-risk client','The branch is running a promotion'], a:1, w:'EDD means deeper checks — source of funds/wealth, senior approval, closer monitoring — reserved for higher-risk relationships.', d:2 },
{ q:'For a company, the “beneficial owner” under Indian KYC rules is generally the natural person who owns or controls more than…', o:['5% of shares','10% of shares','25% of shares or capital/profits','51% of shares'], a:2, w:'Indian KYC directions use a 25% ownership/entitlement threshold for companies (lower percentages apply to some other entity types) — and control must be traced to real people, not just entities.', d:2 },
{ q:'What is the difference between Source of Funds and Source of Wealth?', o:['There is no difference','Source of Funds is where the money for this activity comes from; Source of Wealth is how the customer built their overall fortune','Source of Funds is for banks; Source of Wealth is for insurers','Source of Wealth is checked daily; Source of Funds never'], a:1, w:'SoF explains the origin of the specific funds in the account; SoW explains how the customer accumulated their total wealth. Both matter in EDD.', d:2 },
{ q:'The purpose of adverse media screening is to…', o:['Check whether the customer advertises with the bank','Find credible negative news linking the customer to crime, fraud or sanctions evasion','Monitor stock prices','Translate foreign documents'], a:1, w:'Adverse media (negative news) checks surface credible reports of financial crime or wrongdoing that lists alone may miss.', d:1 },
{ q:'A screening alert turns out to be a different person with a similar name and a different date of birth. This is a…', o:['True match','False positive','Sanctions breach','Case for an STR by itself'], a:1, w:'A false positive is an alert that identifiers (DOB, address, ID numbers) help dismiss — documented carefully, because the dismissal may be reviewed later.', d:2 },
{ q:'“Tipping off” means…', o:['Giving a customer a discount','Informing a customer that they are under investigation or that a report was filed about them','Tipping a colleague about a good restaurant','Escalating an alert to a senior analyst'], a:1, w:'Tipping off is an offence — disclosing that an STR was filed or an investigation is under way can compromise it. Customers are never told.', d:3 },
{ q:'A customer’s account was dormant for two years. This week it received five large transfers that were immediately sent onward, none of which fits the customer’s stated occupation. The right next step is to…', o:['Close the account without recording anything','Review the activity against the customer’s profile, document findings, and escalate through the alert process','Call the customer and ask if they are laundering money','Ignore it — large transfers are normal'], a:1, w:'Activity inconsistent with the known profile is a core transaction-monitoring red flag: review, document, escalate. If suspicion remains, the institution files an STR.', d:2 },
{ q:'Which of these is NOT a typical factor in a customer risk rating?', o:['Customer type and ownership structure','Geography of the customer and counterparties','The customer’s favourite colour','Products and channels the customer uses'], a:2, w:'Risk ratings weigh customer type, geography, products/channels and expected transaction behaviour — personal trivia plays no part.', d:1 },
{ q:'In periodic KYC review, which customers are reviewed most frequently?', o:['Low-risk customers','High-risk customers','Customers with the largest balances only','Customers who complain'], a:1, w:'Review frequency is risk-based: high-risk relationships are refreshed most often, low-risk least often.', d:2 },
{ q:'A special risk in correspondent banking is…', o:['Branches are too far apart','Nested accounts — a respondent bank’s customers transacting through the account without the correspondent seeing them','Currency conversion fees','Time-zone differences'], a:1, w:'Correspondent accounts can be used by the respondent’s own customers (nested/downstream relationships), hiding the real transactors from the correspondent bank’s controls.', d:3 },
{ q:'Trade-Based Money Laundering (TBML) commonly works by…', o:['Trading only on weekdays','Over- or under-invoicing goods, or misrepresenting what was shipped, to move value across borders','Using trade finance at all','Paying suppliers early'], a:1, w:'TBML disguises the movement of illicit value as trade — false invoicing, phantom shipments and multiple invoicing are classic techniques.', d:3 },
{ q:'World-Check is best described as…', o:['A bank’s internal HR portal','A commercial risk-intelligence database used for screening names against sanctions, PEP and adverse-media data','A type of cheque used internationally','A stock exchange'], a:1, w:'World-Check (Refinitiv/LSEG) is one of the screening databases banks use; Actimize and Fircosoft are known transaction-monitoring/screening tools.', d:2 },
{ q:'Payment (transaction) screening differs from customer name screening because it…', o:['Is done once a year','Screens the parties and details inside individual payment messages, in real time, before processing','Only checks staff payments','Replaces customer screening entirely'], a:1, w:'Name screening vets parties at onboarding and on list updates; payment screening checks each transaction’s sender/beneficiary data as it moves.', d:2 },
{ q:'Screening confirms a customer is the same person who appears on a sanctions list. You should…', o:['Process the payment quickly before anyone notices','Stop, block/freeze as policy and law require, and escalate to compliance immediately','Ask the customer to use a different name','Wait for the next periodic review'], a:1, w:'A confirmed sanctions match means no processing: block or freeze per policy, escalate to compliance/sanctions team at once, and never tip off the customer.', d:3 },
{ q:'Which is a classic shell-company red flag?', o:['The company has a website','No real business activity, staff or premises, with nominee directors and a secrecy-jurisdiction registration','The company pays taxes','The company has been a customer for years'], a:1, w:'Shell indicators: no genuine operations, nominee ownership, opaque structures and high-risk jurisdictions — all call for EDD.', d:2 },
{ q:'UBO stands for…', o:['Unified Banking Operations','Ultimate Beneficial Owner','Universal Branch Office','Updated Balance Order'], a:1, w:'The UBO is the real person who ultimately owns or controls an entity — the endpoint of every ownership trace.', d:1 },
{ q:'A cash-intensive business (e.g. a small restaurant chain) applies for an account. The proportionate response is…', o:['Refuse — cash businesses are banned','Onboard with a clear expected-activity profile and closer transaction monitoring for cash patterns','Onboard with no questions because the amounts are small','Ask them to deal only in cash'], a:1, w:'Cash-intensive doesn’t mean prohibited — it means higher inherent risk: set expected cash ranges and monitor against them.', d:2 },
{ q:'A country placed on the FATF “grey list” is…', o:['Banned from all banking','Under increased monitoring for strategic AML/CFT deficiencies, working to an action plan','Exempt from AML rules','A top-rated financial centre'], a:1, w:'Grey-listed jurisdictions have committed to resolving identified deficiencies under increased FATF monitoring — banks apply greater caution, not automatic refusal.', d:3 },
{ q:'You discover a colleague emailing customer KYC documents to their personal email “to work from home”. The best action is to…', o:['Ignore it — everyone does it','Report it through the internal compliance/data-protection channel right away','Join in and ask for a copy','Warn the colleague and say nothing officially'], a:1, w:'Customer documents leaving controlled systems is a data-protection and compliance breach — report through official channels immediately.', d:1 },
{ q:'OFAC — the sanctions authority whose lists banks screen worldwide — belongs to…', o:['India','The United States','The United Kingdom','The United Nations'], a:1, w:'OFAC is the US Office of Foreign Assets Control; the UN and EU maintain their own lists, and Indian banks screen against all applicable ones.', d:2 },
{ q:'A long-standing customer’s transactions still match their profile in value, but they have quietly started dealing with a counterparty in a sanctioned jurisdiction. You should…', o:['Do nothing — the values are normal','Screen the counterparty, review the relationship, and escalate to compliance before further processing','Raise the customer’s limits','Ask the customer to route payments differently'], a:1, w:'Jurisdiction and counterparty risk can change a relationship overnight; sanctions exposure must be escalated regardless of transaction size.', d:3 },
{ q:'Simplified Due Diligence (SDD) may be applied when…', o:['The customer is a PEP','The product and customer are demonstrably low-risk and rules permit reduced measures','The branch is too busy','The customer requests it'], a:1, w:'SDD is the risk-based lighter end of due diligence — permitted only for genuinely low-risk cases defined by regulation and policy.', d:2 },
{ s:'You are reviewing an alert. A customer just below the reporting threshold has made nine cash deposits of ₹9.8 lakh across three branches in one week, each described differently.', q:'This pattern is most consistent with…', o:['Normal salary behaviour','Structuring — splitting transactions to evade the ₹10 lakh reporting threshold','A bank error','Seasonal business income'], a:1, w:'Multiple just-below-threshold transactions across branches is the textbook structuring (smurfing) pattern and a strong STR candidate.', d:2 }
],

'general': [
{ q:'15% of 240 is…', o:['24','30','36','42'], a:2, w:'10% of 240 is 24; 5% is 12; total 36.', d:1 },
{ q:'The average of 10, 20, 30 and 40 is…', o:['20','25','30','35'], a:1, w:'(10+20+30+40) / 4 = 100 / 4 = 25.', d:1 },
{ q:'What comes next in the series 2, 6, 12, 20, 30, …?', o:['36','40','42','44'], a:2, w:'Differences grow: +4, +6, +8, +10, so next is +12 → 42.', d:2 },
{ q:'₹900 is divided between A and B in the ratio 2:1. B receives…', o:['₹450','₹300','₹600','₹150'], a:1, w:'Three parts in total; each part is ₹300; B gets one part.', d:1 },
{ q:'A car travels at 60 km/h for 2.5 hours. How far does it go?', o:['120 km','140 km','150 km','180 km'], a:2, w:'Distance = speed × time = 60 × 2.5 = 150 km.', d:1 },
{ q:'A price rises 20%, then falls 20%. Compared with the start, the final price is…', o:['The same','4% lower','4% higher','40% lower'], a:1, w:'100 → 120 → 96. Equal percentage rises and falls do not cancel, because the second is calculated on a bigger base.', d:2 },
{ q:'Simple interest on ₹10,000 at 8% per year for 2 years is…', o:['₹800','₹1,600','₹1,664','₹16,000'], a:1, w:'SI = P × R × T / 100 = 10,000 × 8 × 2 / 100 = ₹1,600.', d:1 },
{ q:'Which number is the odd one out: 121, 131, 137, 139?', o:['121','131','137','139'], a:0, w:'131, 137 and 139 are prime; 121 = 11 × 11.', d:2 },
{ q:'If today is Wednesday, what day will it be 10 days from now?', o:['Friday','Saturday','Sunday','Monday'], a:1, w:'10 days = 1 week + 3 days; Wednesday + 3 = Saturday.', d:1 },
{ q:'In Excel, which function adds up a range of cells?', o:['TOTAL','SUM','ADD','COUNT'], a:1, w:'SUM(range) totals values; COUNT counts entries.', d:1 },
{ q:'What is a pivot table used for?', o:['Drawing charts only','Summarising and aggregating large sets of data by categories','Merging two workbooks','Protecting cells with a password'], a:1, w:'Pivot tables group and total data (e.g. sales by city by month) without writing formulas for each combination.', d:2 },
{ q:'45 is what percentage of 180?', o:['20%','25%','40%','45%'], a:1, w:'45 / 180 = 0.25 = 25%.', d:1 },
{ q:'Solve: 3x + 5 = 20. x = …', o:['3','4','5','6'], a:2, w:'3x = 15, so x = 5.', d:1 },
{ q:'Five workers finish a job in 12 days. Working at the same rate, ten workers would take…', o:['24 days','12 days','8 days','6 days'], a:3, w:'Doubling the workers halves the time: 12 / 2 = 6 days.', d:2 },
{ s:'A customer on the phone is shouting about a failed payment and threatens to “go to the media”.', q:'Your best first move is to…', o:['Match their volume so they take you seriously','Listen fully without interrupting, acknowledge the problem, then explain the next step and timeline','Transfer them immediately to anyone else','Promise a refund on the spot to end the call'], a:1, w:'De-escalation starts with listening and acknowledgement; specific, honest next steps calm most situations. Never promise what you cannot approve.', d:1 },
{ s:'Your manager gives you two tasks, both marked urgent, and you can only finish one today.', q:'The most professional approach is to…', o:['Pick the easier one silently','Tell your manager early, explain the clash, and ask (or recommend) which takes priority','Do both badly','Wait until end of day and apologise'], a:1, w:'Surfacing a priority clash early — with a recommendation — lets the person who owns the priorities decide.', d:1 },
{ q:'In an interview, “Why should we hire you?” is best answered by…', o:['Saying you desperately need the job','Connecting your specific skills and evidence to what this role actually needs','Praising the company’s office','Listing every subject you studied since school'], a:1, w:'Hiring answers work when they map your proven skills to the employer’s stated needs — specifics beat adjectives.', d:2 },
{ q:'Asked about your biggest weakness, the strongest approach is to…', o:['Say you have none','Name a strength disguised as a weakness, like “I work too hard”','Name a real, job-safe weakness and the concrete steps you are taking on it','Criticise your previous manager'], a:2, w:'Interviewers rate honesty plus a visible improvement system; scripted disguises are recognised instantly.', d:2 },
{ s:'A teammate presents your analysis in a team meeting as their own work.', q:'The best first response is to…', o:['Interrupt and accuse them in front of everyone','Raise it privately with the teammate first, with facts, and escalate only if it repeats','Quietly stop sharing anything with the team','Do the same to them next week'], a:1, w:'Private, factual conversation first solves most credit issues without damaging the team; escalate with evidence if the pattern continues.', d:2 },
{ s:'A senior colleague’s instructions for a task are genuinely unclear, and guessing wrong wastes a day.', q:'You should…', o:['Guess and hope','Ask focused clarifying questions before starting — what output, in what format, by when','Wait a day to see if it becomes clear','Do the task three different ways'], a:1, w:'Thirty seconds of clarifying questions is cheaper than a day of rework; good seniors expect them.', d:1 },
{ s:'You realise a report you sent yesterday contains a wrong figure.', q:'The right move is to…', o:['Say nothing — nobody may notice','Inform your manager immediately, send a corrected version, and flag what changed','Quietly edit the file in the shared drive','Blame the data source'], a:1, w:'Owning an error early, with the correction attached, protects decisions made from the report and builds trust.', d:2 },
{ q:'Which habit most improves accuracy in high-volume data entry?', o:['Typing faster','Working without breaks','A verify-as-you-go routine — source checks, totals and spot re-checks','Listening to music loudly'], a:2, w:'Accuracy comes from built-in verification (check totals, sample re-checks), not from speed.', d:1 },
{ s:'A friend who banks where you work asks you to “just check” a relative’s account balance.', q:'You should…', o:['Check it — it is a small favour','Refuse politely: customer data can only be accessed for a genuine business reason','Check it but not tell anyone the number','Ask them to message the request so there is a record'], a:1, w:'Accessing customer data without a business need is a serious breach, however kind the intention — confidentiality rules have no friends-and-family exception.', d:1 },
{ q:'The clearest sentence for a professional email is…', o:['“This is to kindly intimate you regarding the needful, do the same at the earliest.”','“Please send the signed form by Friday so we can process your application.”','“As per our telephonic conversation, the needful will be done by us.”','“Your good self is requested to revert back on the same.”'], a:1, w:'Plain words, one clear ask, one clear deadline — that is what professional clarity looks like.', d:1 },
{ q:'In an interview you are asked a technical question you genuinely cannot answer. The best response is to…', o:['Invent a confident-sounding answer','Say you don’t know, explain how you would find out, and offer a related thing you do know','Change the subject to your strengths','Stay silent until the interviewer moves on'], a:1, w:'Honesty plus a credible method for finding the answer scores better than bluffing — interviewers test exactly this.', d:2 },
{ s:'You are working from home and finish a task two hours early, with nothing else assigned.', q:'The professional move is to…', o:['Stay offline so nobody assigns more','Proactively update your manager on status and ask what to pick up next','Start a personal project on office time','Log the task as still in progress'], a:1, w:'Proactive status updates are how remote trust is built — visibility plus willingness beats silent availability.', d:2 },
{ q:'RTGS is generally preferred over NEFT when…', o:['Sending a small amount to a friend','Settling a high-value payment that must move in real time, individually','Paying a phone bill','The bank is closed'], a:1, w:'RTGS settles high-value transfers one-by-one in real time; NEFT settles in batches and suits everyday transfers.', d:3 },
{ s:'A walk-in customer refuses to provide KYC documents, saying “other banks don’t ask me all this”.', q:'The correct response is to…', o:['Open the account and collect documents later','Politely explain that KYC documents are a legal requirement for every regulated bank, and offer to help them complete it','Ask a senior to waive the rule for this customer','Suggest they open the account in someone else’s name'], a:1, w:'KYC is a regulatory requirement, not a branch preference — explain it respectfully, help with the process, and never bypass or proxy it.', d:2 },
{ q:'Which percentage change is correct? A value moves from 80 to 100.', o:['+20%','+25%','+80%','+125%'], a:1, w:'Change = 20 on a base of 80 → 20/80 = 25%.', d:2 },
{ q:'A professional email is strongest when the subject line…', o:['Is left blank to create curiosity','States the topic and needed action in a few words, e.g. “Form pending: signature needed by Fri”','Says only “Important”','Contains the whole message'], a:1, w:'Specific subjects get opened, understood and acted on; vague ones get postponed.', d:1 },
{ q:'You are asked in an interview, “Where do you see yourself in three years?” A strong fresher answer…', o:['“As your manager.”','Ties growth to this field — deeper skill, more responsibility, a concrete next step','“I will have started my own company.”','“Wherever life takes me.”'], a:1, w:'Employers look for direction within the field and role they are hiring for — ambition with a plausible path beats slogans.', d:3 },
{ q:'What does a bank’s KYC process primarily protect against?', o:['Slow internet','Fraud, money laundering and regulatory penalties','Customers opening too many accounts for fun','Staff overtime'], a:1, w:'Identity verification and monitoring keep criminals out of the system and keep the institution compliant.', d:1 },
{ s:'Two of your regular tasks collide with a surprise audit request due tomorrow.', q:'Your best sequence is to…', o:['Panic quietly and work late without telling anyone','Prioritise the audit (fixed external deadline), inform your manager of the impact on the other tasks, and agree new dates','Ignore the audit — it is not your regular job','Delegate everything to a new joiner'], a:1, w:'Fixed external deadlines win; the skill is communicating the knock-on impact early and renegotiating the rest explicitly.', d:3 }
]
};

BANKS['data-science-ai'] = [
{ q:'In Python, the key difference between a list and a tuple is…', o:['Lists are faster','Tuples are immutable — their contents cannot be changed after creation','Tuples can only store numbers','Lists cannot be indexed'], a:1, w:'Lists are mutable; tuples are immutable and are used for fixed collections.', d:1 },
{ q:'Overfitting means a model…', o:['Is too simple to learn anything','Performs well on training data but poorly on new, unseen data','Takes too long to train','Uses too little data by definition'], a:1, w:'An overfit model memorises training noise instead of learning general patterns.', d:1 },
{ q:'Supervised learning differs from unsupervised learning because it…', o:['Uses labelled examples with known outcomes to learn from','Needs no data','Only works on images','Is always more accurate'], a:0, w:'Supervised learning trains on labelled data (input → known answer); unsupervised learning finds structure in unlabelled data.', d:1 },
{ q:'Why split data into training and test sets?', o:['To make the file smaller','To honestly evaluate the model on data it has never seen','Because the library requires it','To remove duplicates'], a:1, w:'Testing on unseen data reveals whether the model generalises or merely memorised.', d:1 },
{ q:'Precision in classification is…', o:['Correct predictions ÷ all predictions','True positives ÷ all predicted positives','True positives ÷ all actual positives','Errors ÷ total rows'], a:1, w:'Precision asks: of everything the model flagged positive, how much was actually positive? Recall uses actual positives as the denominator.', d:2 },
{ q:'RMSE is a metric used mainly for…', o:['Classification accuracy','Regression — it measures the average size of prediction errors, in the target’s units','Clustering quality','Ranking web pages'], a:1, w:'Root Mean Squared Error penalises large errors and is read in the same units as the predicted value.', d:2 },
{ q:'In pandas, a DataFrame is best compared to…', o:['A single number','A table with rows and columns, like a spreadsheet or SQL table','An image file','A neural network'], a:1, w:'A DataFrame is a labelled 2-D table — the workhorse structure for data analysis in Python.', d:1 },
{ q:'Which SQL clause filters groups after aggregation?', o:['WHERE','ORDER BY','HAVING','LIMIT'], a:2, w:'WHERE filters rows before grouping; HAVING filters the groups produced by GROUP BY.', d:2 },
{ q:'A dataset has missing values in a numeric column. A reasonable first approach is to…', o:['Delete the whole dataset','Understand why they are missing, then choose: fill with median/mean, model them, or drop — and document the choice','Replace them all with zero without thinking','Ignore them; every tool handles them perfectly'], a:1, w:'The right treatment depends on why data is missing and how much; silent defaults corrupt conclusions.', d:2 },
{ q:'“Correlation does not imply causation” means…', o:['Correlated variables are never related','Two things moving together does not prove one causes the other — a third factor may drive both','Causation is impossible to study','Correlation is useless'], a:1, w:'Ice-cream sales correlate with drowning — both are driven by summer. Correlation suggests; it does not prove.', d:1 },
{ q:'In machine learning, a “feature” is…', o:['The final prediction','An input variable the model learns from','A bug in the code','The training dataset’s file name'], a:1, w:'Features are the measurable inputs (age, amount, clicks); the label/target is what you predict.', d:1 },
{ q:'The “label” in a supervised dataset is…', o:['The column you are trying to predict','The person who collected the data','A chart title','The row number'], a:0, w:'Labels are the known answers during training — e.g. “fraud” / “not fraud” for each past transaction.', d:1 },
{ q:'An LLM (Large Language Model) is…', o:['A spreadsheet add-in','A model trained on very large amounts of text to predict and generate language','A type of database','A programming language'], a:1, w:'LLMs learn statistical patterns of language from huge text corpora — the technology behind tools like ChatGPT.', d:2 },
{ s:'Your churn model scored 95% in testing last quarter but has dropped to 70% on this month’s live customers.', q:'The most likely explanation to investigate first is…', o:['The model file is corrupted','Customer behaviour has drifted — the live data no longer matches the training data','The test set was too large','Python updated itself'], a:1, w:'Data/concept drift is the classic cause of production model decay; monitoring and retraining pipelines exist for exactly this.', d:3 },
{ s:'A manager asks for a chart comparing total sales across five product categories.', q:'The clearest default choice is a…', o:['Pie chart with 3-D effects','Bar chart','Scatter plot','Line chart of stock prices'], a:1, w:'Bars make category comparisons readable at a glance; lines show trends over time, scatter shows relationships.', d:1 },
{ s:'A CSV has 20 million rows and your laptop freezes when Excel opens it.', q:'The practical move is to…', o:['Buy more RAM only','Process it with Python/pandas in chunks, or load it into a database and query with SQL','Print it','Give up on the analysis'], a:1, w:'Beyond a million or so rows, code and databases — not spreadsheets — are the right tools.', d:2 },
{ s:'A hiring model trained on ten years of one company’s past decisions starts rejecting most women applicants.', q:'The core problem is…', o:['The model is too accurate','Historical bias in the training data — the model learned yesterday’s biased decisions','The applicants are unqualified','Not enough features'], a:1, w:'Models learn the patterns in their data, including unfair ones; auditing outcomes by group is part of responsible ML work.', d:3 },
{ q:'What does “ETL” stand for in a data pipeline?', o:['Extract, Transform, Load','Edit, Test, Launch','Excel To Linux','Estimate, Track, Log'], a:0, w:'ETL pulls data from sources (extract), cleans/shapes it (transform), and stores it for use (load).', d:2 },
{ q:'A confusion matrix compares…', o:['Two programmers’ code','Predicted classes against actual classes — true/false positives and negatives','Training time across models','File sizes'], a:1, w:'The matrix shows exactly where a classifier confuses classes, which guides which metric and fix matter.', d:3 },
{ q:'Before modelling, the first thing to do with a new dataset is…', o:['Train the most complex model available','Explore it — size, types, missing values, odd ranges — and understand what each column means','Delete outliers blindly','Send it to stakeholders'], a:1, w:'Exploratory analysis prevents the classic failure: a brilliant model of the wrong column or corrupted data.', d:2 }
];

BANKS['java-fullstack'] = [
{ q:'The JVM is responsible for…', o:['Writing Java code','Running compiled Java bytecode on any platform','Designing databases','Styling web pages'], a:1, w:'Java compiles to bytecode; the JVM executes it — the basis of “write once, run anywhere”.', d:1 },
{ q:'JDK, JRE, JVM — which is correct?', o:['They are three names for the same thing','JDK (development kit) includes the JRE (runtime), which includes the JVM','JVM includes the JDK','JRE is only for mobile phones'], a:1, w:'Developers install the JDK; it contains the JRE (libraries + JVM) needed to run Java programs.', d:2 },
{ q:'Which is NOT one of the four OOP pillars?', o:['Encapsulation','Inheritance','Polymorphism','Compilation'], a:3, w:'The pillars are encapsulation, inheritance, polymorphism and abstraction; compilation is just how code is built.', d:1 },
{ q:'An interface in Java is used to…', o:['Store database rows','Define a contract of methods that classes agree to implement','Replace all classes','Make code run faster'], a:1, w:'Interfaces specify what a class must do without dictating how — the basis of flexible, testable design.', d:2 },
{ q:'ArrayList vs LinkedList — the everyday rule is…', o:['LinkedList is always better','ArrayList is the default choice: fast random access; LinkedList helps mainly with frequent insertions at known positions','They are identical','ArrayList cannot grow'], a:1, w:'ArrayList’s array backing gives O(1) index access; LinkedList trades that for cheap node insertions.', d:2 },
{ q:'Spring Boot is popular because it…', o:['Replaces the JVM','Provides auto-configuration and embedded servers so production-ready apps start with minimal setup','Is a database','Only builds mobile apps'], a:1, w:'Spring Boot’s starters and auto-configuration remove most boilerplate configuration from Spring applications.', d:1 },
{ q:'In a Spring REST API, @RestController marks a class whose methods…', o:['Render HTML pages only','Handle HTTP requests and return data (typically JSON) directly as the response body','Connect to the database','Run scheduled jobs only'], a:1, w:'@RestController = @Controller + @ResponseBody: return values are serialised to the response, usually JSON.', d:2 },
{ q:'HTTP status 404 means…', o:['Server crashed','The requested resource was not found','The request succeeded','Access is forbidden'], a:1, w:'404 = Not Found; 403 = forbidden; 500 = internal server error; 200 = OK.', d:1 },
{ q:'GET differs from POST mainly in that GET…', o:['Is more secure','Retrieves data without changing server state; POST submits data to create or change something','Is faster by law','Cannot carry parameters'], a:1, w:'GET is safe/idempotent retrieval (parameters in the URL); POST sends a body to create or process.', d:1 },
{ q:'In React, “props” are…', o:['Internal state of a component','Inputs passed from a parent component to a child','CSS files','Database connections'], a:1, w:'Props flow down from parent to child and are read-only in the child; state is the component’s own changing data.', d:2 },
{ q:'Which HTML tag is semantic (describes its meaning)?', o:['<div>','<span>','<article>','<b>'], a:2, w:'Semantic tags like <article>, <nav> and <header> describe content structure — better for accessibility and SEO than generic divs.', d:1 },
{ q:'CSS Flexbox is mainly used to…', o:['Animate 3-D graphics','Lay out items in one dimension — a row or a column — with flexible spacing and alignment','Connect to an API','Store variables'], a:1, w:'Flexbox handles one-dimensional layouts; Grid handles two-dimensional ones.', d:1 },
{ q:'A primary key in a database table…', o:['Can be empty for some rows','Uniquely identifies each row and cannot be NULL','Is always a name field','Speeds up printing'], a:1, w:'Primary keys enforce row identity — unique and never NULL.', d:1 },
{ q:'REST APIs are described as “stateless” because…', o:['They store nothing anywhere','Each request carries everything the server needs; the server keeps no client session between requests','They are free to use','They never return errors'], a:1, w:'Statelessness makes REST services simple to scale — any server instance can handle any request.', d:2 },
{ s:'Your deployed API suddenly returns 500 errors for every user after a release.', q:'Your first diagnostic step is to…', o:['Rewrite the frontend','Check the server logs and what changed in the release','Ask users to clear their cache','Increase the database size'], a:1, w:'Server-side 500s right after a deploy point at the change and the logs — start where the evidence is.', d:2 },
{ s:'A web page you built loads in 9 seconds. Users are leaving.', q:'A sensible first round of checks is…', o:['Change the colour scheme','Look at image sizes, number of requests and render-blocking assets in the browser’s network/performance tools','Buy a bigger server immediately','Remove all JavaScript'], a:1, w:'Most slow pages are heavy, not underpowered: oversized images and blocking assets dominate load time.', d:3 },
{ q:'Git is used to…', o:['Host websites only','Track changes in code, collaborate and roll back when needed','Write Java automatically','Test APIs'], a:1, w:'Version control records every change with history — the safety net of all team development.', d:1 },
{ q:'A try/catch block in Java is for…', o:['Making loops faster','Handling exceptions so a failure can be logged, recovered from, or reported cleanly','Connecting to databases','Declaring variables'], a:1, w:'Exceptions signal abnormal situations; try/catch decides what the program does instead of crashing blindly.', d:1 },
{ q:'“Explain your project” in an interview is best handled by…', o:['Reading the code aloud line by line','A short structured story: the problem, your role, the key choices, the outcome — then invite questions','Listing every technology you have ever opened','Describing only the hardest bug'], a:1, w:'Structure (problem → role → decisions → result) makes your contribution and thinking easy to evaluate.', d:2 },
{ q:'In Java, “==” on two String objects compares…', o:['Their characters','Whether the references point to the same object — use .equals() to compare content','Their lengths','Nothing; it is a syntax error'], a:1, w:'The classic Java trap: == compares references for objects; .equals() compares values.', d:3 }
];

BANKS['dbi'] = [
{ q:'A data warehouse differs from a day-to-day operational database mainly in that it is…', o:['Smaller','Optimised for analysis over history (OLAP) rather than live transactions (OLTP)','Only for backups','Accessible to everyone'], a:1, w:'Operational systems run the business (OLTP); warehouses consolidate history for reporting and analysis (OLAP).', d:1 },
{ q:'In a star schema, the centre table holds…', o:['Dimension descriptions','Facts — measurable events like sales amounts, with keys to dimensions','User passwords','Report templates'], a:1, w:'Fact tables store measures and foreign keys; dimension tables around them hold the descriptive context (product, city, date).', d:2 },
{ q:'An index in a database speeds up…', o:['Inserting into every table','Finding rows that match lookups — at the cost of some storage and slower writes','Backups','Network traffic'], a:1, w:'Indexes are like a book’s index: faster reads, modest write/storage cost.', d:1 },
{ q:'Normalisation in database design aims to…', o:['Make tables as wide as possible','Reduce duplication and update anomalies by organising data into related tables','Encrypt the data','Remove the need for keys'], a:1, w:'Splitting data so each fact lives in one place prevents inconsistent updates.', d:2 },
{ q:'WHERE and HAVING differ in that…', o:['They are synonyms','WHERE filters rows before grouping; HAVING filters groups after aggregation','HAVING is faster','WHERE works only on text'], a:1, w:'The classic SQL interview pair — row filter vs group filter.', d:1 },
{ q:'A LEFT JOIN returns…', o:['Only matching rows','All rows from the left table, with matching right-table data where it exists (NULLs otherwise)','Rows unique to both tables','The tables merged permanently'], a:1, w:'LEFT JOIN preserves the left side fully — essential when missing matches are themselves information.', d:2 },
{ q:'DAX is…', o:['A database server','The formula/calculation language used in Power BI (and Excel data models)','A chart type','A file format'], a:1, w:'DAX expressions (CALCULATE, SUMX, filters) power measures in Power BI reports.', d:1 },
{ q:'ETL stands for…', o:['Extract, Transform, Load','Excel Table Layout','Enterprise Tape Library','Estimate, Test, Launch'], a:0, w:'Extract from sources, transform to a clean consistent shape, load into the target (often a warehouse).', d:1 },
{ s:'A Power BI dashboard shows sales exactly double the finance team’s figures for the same month.', q:'The most likely cause to check first is…', o:['The finance team is wrong','A join in the model is duplicating rows (fan-out), or a filter/context is missing','The colours are misleading','Power BI cannot do sums'], a:1, w:'Doubled measures classically come from many-to-many join duplication or a missing filter — verify row counts at each model step.', d:2 },
{ q:'A NULL in a database column means…', o:['Zero','An empty string','The value is absent/unknown — not the same as zero or blank','An error occurred'], a:2, w:'NULL is “no value”; it behaves specially in comparisons and aggregations, which is why it trips up reports.', d:2 },
{ s:'A nightly report query that used to take 2 minutes now takes 40.', q:'Reasonable first checks are…', o:['Complain to the vendor','Data volume growth, missing/changed indexes, and whether the query plan changed','Rewrite every report','Delete old data immediately'], a:1, w:'Slowdowns usually trace to growth or plan changes — measure before rebuilding.', d:3 },
{ q:'A “slowly changing dimension” problem is about…', o:['Slow networks','Handling changes to descriptive data over time — e.g. a customer moving city — while keeping history meaningful','Compressing tables','Slow typists'], a:1, w:'SCD strategies (overwrite, add row, add column) decide how history is preserved when attributes change.', d:3 },
{ q:'GROUP BY is used to…', o:['Sort the output alphabetically','Aggregate rows into groups so functions like SUM and COUNT compute per group','Join two tables','Rename columns'], a:1, w:'GROUP BY defines the buckets aggregates are computed over.', d:1 },
{ q:'A KPI is…', o:['A database table','A measurable value that shows progress toward a business objective','A type of chart','A user role'], a:1, w:'Key Performance Indicators connect data work to decisions — revenue per customer, churn rate, on-time delivery.', d:1 },
{ q:'Data quality checks in a pipeline typically verify…', o:['That the dashboard looks nice','Completeness, uniqueness, validity and freshness of the data','That files are large','User passwords'], a:1, w:'Pipelines assert expectations (no null keys, no duplicates, fresh data) so bad data fails loudly, not silently.', d:2 },
{ s:'Two departments argue because their “active customers” numbers differ by 8%.', q:'The most probable root cause is…', o:['One department is lying','Different definitions or filters behind the same label','Rounding','A broken keyboard'], a:1, w:'Metric disputes are usually definition disputes — align the business definition first, then the SQL follows.', d:3 },
{ q:'In SQL, COUNT(*) vs COUNT(column) differ when…', o:['The table is large','The column contains NULLs — COUNT(column) skips them, COUNT(*) counts all rows','Always; they are never equal','Only in Power BI'], a:1, w:'A classic gotcha: COUNT(column) ignores NULL values in that column.', d:2 },
{ q:'Power Query (in Excel/Power BI) is used to…', o:['Write final reports','Connect to sources and clean/shape data with repeatable steps before analysis','Send emails','Design logos'], a:1, w:'Power Query records transformation steps so refreshed data is cleaned the same way every time.', d:2 },
{ q:'Asked to “just quickly pull the numbers” for a new, undefined request, the professional analyst first…', o:['Starts writing SQL immediately','Clarifies what decision the numbers support, the exact definition and the timeframe','Sends last month’s file','Asks a colleague to guess'], a:1, w:'Thirty seconds of definition questions prevents the most common analytics rework: precise answers to the wrong question.', d:2 },
{ q:'“Garbage in, garbage out” in BI means…', o:['Reports should be printed on recycled paper','Conclusions can never be better than the quality of the underlying data','Old reports should be deleted','Dashboards need more charts'], a:1, w:'Data quality upstream caps the value of everything downstream — the analyst’s first loyalty is to the data’s integrity.', d:1 }
];

BANKS['python-fullstack'] = [
{ q:'Python lists and tuples differ in that…', o:['Tuples are mutable','Lists are mutable; tuples are not','Lists hold only strings','Tuples are always faster at everything'], a:1, w:'Use lists for collections that change; tuples for fixed records.', d:1 },
{ q:'A Python dictionary stores…', o:['Only numbers','Key–value pairs for fast lookup by key','HTML pages','Images'], a:1, w:'Dicts map keys to values — the natural fit for records like user profiles or settings.', d:1 },
{ q:'Indentation in Python is…', o:['Purely decorative','Meaningful — it defines code blocks (loops, functions, conditions)','Required only in classes','Ignored by the interpreter'], a:1, w:'Python uses indentation instead of braces; inconsistent indentation is a syntax error.', d:1 },
{ q:'pip is used to…', o:['Run Python faster','Install and manage third-party Python packages','Write HTML','Create databases'], a:1, w:'pip installs libraries from PyPI (e.g. requests, flask, pandas).', d:1 },
{ q:'A virtual environment (venv) exists so that…', o:['Python runs in the cloud','Each project can pin its own package versions without breaking other projects','Code becomes private','The computer uses less electricity'], a:1, w:'Isolated environments prevent the classic “upgrading one project broke another” problem.', d:2 },
{ q:'Django and Flask are…', o:['Databases','Python web frameworks for building backends and APIs','Testing tools','CSS libraries'], a:1, w:'Flask is minimal; Django is batteries-included (ORM, admin, auth) — both serve web backends.', d:1 },
{ q:'An ORM lets developers…', o:['Avoid databases entirely','Work with database tables as programming objects instead of writing raw SQL for everything','Design page layouts','Compress images'], a:1, w:'Object-Relational Mappers translate between classes and tables; raw SQL remains available for complex queries.', d:2 },
{ q:'Which HTTP method is typically used to update an existing resource?', o:['GET','PUT (or PATCH for partial updates)','DELETE','HEAD'], a:1, w:'POST creates, GET reads, PUT/PATCH update, DELETE removes — the REST convention.', d:2 },
{ s:'Your Python script crashes with KeyError: "price" on some products only.', q:'The robust fix is…', o:['Restart the script','Use .get("price", default) or check membership — some records genuinely lack the field','Delete those products','Ignore the error'], a:1, w:'Real data is irregular; defensive lookups with sensible defaults beat crashes.', d:2 },
{ s:'A page loads data with one query for a list, then one extra query per item — 1,000 items means 1,001 queries and a slow page.', q:'This problem is known as…', o:['Caching','The N+1 query problem','Indexing','Sharding'], a:1, w:'Fix N+1 by fetching related data in bulk (joins/prefetch) instead of per-item queries.', d:3 },
{ q:'Python strings are immutable, which means…', o:['They cannot be printed','Operations like .upper() return a new string; the original is unchanged','They cannot contain spaces','They are stored in tuples only'], a:1, w:'Immutability prevents accidental in-place edits — methods return new strings.', d:2 },
{ q:'A try/except block should be used to…', o:['Hide all bugs silently','Handle expected failure cases (bad input, network errors) with a deliberate response','Replace testing','Make code shorter'], a:1, w:'Catch specific exceptions you can act on; blanket silent catching hides real bugs.', d:2 },
{ q:'JSON is…', o:['A Python-only format','A text format for structured data (objects, arrays) used by APIs everywhere','A database','An image format'], a:1, w:'JSON is language-independent — the default data language of web APIs.', d:1 },
{ q:'In Git, a branch lets you…', o:['Delete history','Develop a feature in isolation and merge it when ready','Host the website','Run the code'], a:1, w:'Branches make parallel work and safe experimentation possible.', d:1 },
{ q:'Python is described as an interpreted language because…', o:['It translates to English','Source code is executed by an interpreter at runtime rather than shipped as machine code','It only runs online','It interprets HTML'], a:1, w:'The interpreter executes code directly (compiling to bytecode internally) — no separate compile step for the developer.', d:1 },
{ q:'In React, a component’s “state” is…', o:['Its CSS file','Data the component manages that, when changed, re-renders the UI','The server’s database','A prop from the parent'], a:1, w:'State drives dynamic UIs: update state, and React re-renders what changed.', d:2 },
{ s:'An interviewer asks: “Your API endpoint works for 10 users but times out at 10,000. What do you look at?”', q:'A strong answer starts with…', o:['“Buy a bigger server” as the only answer','Finding the bottleneck first — database queries, caching opportunities, and what can be paginated or made asynchronous','Rewriting everything in another language','Limiting signups'], a:1, w:'Scaling answers score when they diagnose before prescribing: measure, then cache/optimise the actual bottleneck.', d:3 },
{ q:'The purpose of requirements.txt (or similar) in a Python project is to…', o:['List the team members','Declare the project’s package dependencies and versions so the environment can be recreated','Store passwords','Hold test data'], a:1, w:'A pinned dependency list makes “works on my machine” reproducible anywhere.', d:2 },
{ q:'list comprehension [x*2 for x in nums] is…', o:['A syntax error','A concise way to build a new list by transforming each element','A loop that never ends','Only for strings'], a:1, w:'Comprehensions express map/filter patterns readably in one line.', d:2 },
{ q:'When an interviewer says “walk me through your project”, they most want to hear…', o:['Every file name','The problem, your specific contribution, the technologies and why, and what you would improve','Only the salary you expect','A tutorial on Python basics'], a:1, w:'They are evaluating ownership and judgement, not recitation.', d:1 }
];

BANKS['qa-testing'] = [
{ q:'A test case is…', o:['A bug report','A defined set of inputs, steps and expected results to verify one specific behaviour','A release plan','A type of server'], a:1, w:'Test cases make verification repeatable — anyone can run the same steps and judge the same expected outcome.', d:1 },
{ q:'Regression testing means…', o:['Testing only new features','Re-testing existing functionality to confirm recent changes did not break what already worked','Testing by end users','Testing under heavy load'], a:1, w:'Most production bugs are old features broken by new changes — regression suites guard exactly that.', d:1 },
{ q:'Severity vs priority: a bug can be…', o:['High severity and high priority always together','High severity (deep technical impact) but low priority (rarely hit), and vice-versa — they are separate judgements','The same thing','Set only by developers'], a:1, w:'Severity = impact of the defect; priority = urgency of fixing it. A typo on the payment page may be low severity but high priority.', d:2 },
{ q:'Smoke testing is…', o:['Testing with the lights off','A quick, broad check that a build is stable enough for deeper testing','Testing by customers','Load testing'], a:1, w:'Smoke tests confirm the basics work; sanity tests check a specific fix or area in depth.', d:1 },
{ q:'Boundary Value Analysis focuses on…', o:['Random data','Testing at the edges of valid ranges — min, just below, just above, max — where defects cluster','Only negative numbers','Testing on the first day'], a:1, w:'If a field accepts 1–100, defects hide at 0, 1, 100 and 101 — boundaries, not middles.', d:2 },
{ q:'Equivalence partitioning reduces test effort by…', o:['Deleting test cases','Grouping inputs that should behave the same and testing one representative from each group','Running tests in parallel','Skipping documentation'], a:1, w:'If one value from a class passes, its equivalents usually behave the same — test representatives, not every value.', d:2 },
{ q:'Selenium is used for…', o:['Designing test logos','Automating web browser interactions for UI testing','Writing user stories','Deploying code'], a:1, w:'Selenium drives real browsers via code — the standard tool for web UI automation.', d:1 },
{ q:'UAT (User Acceptance Testing) is performed…', o:['Only by the QA lead','By end users or business representatives, to confirm the system meets real business needs before go-live','By the database','After the product is retired'], a:1, w:'QA verifies specifications; UAT validates fitness for real-world use — the business signs off.', d:1 },
{ s:'You find a bug but cannot reproduce it consistently.', q:'The most useful next step is to…', o:['Log “bug exists” and move on','Gather evidence — exact steps, environment, data, logs/screenshots — and note the reproduction rate honestly','Assume it is fixed','Blame the developer'], a:1, w:'Intermittent bugs are solved by evidence and patterns, not by louder claims; a partial reproduction rate is valuable information.', d:2 },
{ s:'Release is tomorrow. You discover a critical payment bug today.', q:'The professional action is to…', o:['Stay silent — the deadline matters more','Raise it immediately with evidence and impact, document the risk, and let the release decision be made knowingly','Fix the code yourself quietly','Test less so it is not found again'], a:1, w:'QA’s duty is informed decisions: surface critical risk fast, with facts. Hiding it converts a managed delay into a public failure.', d:2 },
{ q:'Black-box testing means testing…', o:['Only at night','Behaviour through inputs and outputs, without looking at internal code','The server hardware','With the screen off'], a:1, w:'Black-box = functional view; white-box = testing with knowledge of internal code paths.', d:1 },
{ q:'A test plan typically documents…', o:['Only the tester’s name','Scope, approach, environments, entry/exit criteria, risks and schedule for testing','Marketing slogans','Salary bands'], a:1, w:'The plan aligns everyone on what will and will not be tested, and what “done” means.', d:2 },
{ q:'Entry criteria for testing are…', o:['The tester’s mood','Conditions that must be true before testing starts — e.g. a deployed build, test data, smoke pass','The office entry rules','Exit criteria repeated'], a:1, w:'Entry/exit criteria stop chaotic starts and premature sign-offs.', d:2 },
{ q:'API testing differs from UI testing because it…', o:['Needs no test cases','Verifies the service layer directly — requests, responses, status codes, data — without the interface','Only uses Excel','Is done by users'], a:1, w:'API tests are faster, more stable and catch contract/data errors that UI tests surface late.', d:2 },
{ s:'A developer insists your bug “works as designed”.', q:'The strongest way to settle it is to…', o:['Argue louder','Point to the requirement/specification and the exact expected-vs-actual behaviour; involve the product owner if the spec is ambiguous','Delete the bug','Test a different feature'], a:1, w:'Requirements are the referee. If the spec itself is unclear, the PO’s clarification becomes the new record.', d:3 },
{ q:'A defect’s “lifecycle” refers to…', o:['How long the tester has worked there','The states a bug passes through — new, assigned, fixed, retested, closed (or reopened/deferred)','The release calendar','Hardware lifespan'], a:1, w:'Tracked states keep ownership and verification explicit — especially the retest after a fix.', d:1 },
{ q:'Test data should…', o:['Be someone’s real personal data copied from production without thought','Cover valid, invalid and boundary cases, and be handled with privacy care','Always be a single record','Never be refreshed'], a:1, w:'Good test data makes scenarios reproducible; real personal data in test systems is a privacy risk and often prohibited.', d:3 },
{ q:'Performance testing checks…', o:['How the code looks','How the system behaves under load — response times, throughput, stability','Spelling in the UI','Tester speed'], a:1, w:'A page that works for one user may collapse for ten thousand; performance tests find that ceiling early.', d:3 },
{ q:'In an interview, “how would you test this login page?” rewards candidates who…', o:['Name one tool','Think in categories: valid/invalid credentials, empty fields, security (lockouts, masking), sessions, and usability — before tools','Ask for the test cases','Say “manually”'], a:1, w:'Structured coverage thinking — functional, negative, security, edge — is the skill being assessed.', d:2 },
{ q:'“Shift-left” testing means…', o:['Testing only on Mondays','Involving testing thinking early — reviews, testable requirements, unit tests — instead of only at the end','Moving the QA team’s desks','Testing after release'], a:1, w:'Defects are cheapest where they are born: in requirements and design, not in production.', d:3 }
];

BANKS['stom'] = [
{ q:'SLA stands for…', o:['Service Level Agreement','System Login Access','Software Licence Authority','Support Line Allocation'], a:0, w:'An SLA is the formal commitment on service levels — e.g. response within 30 minutes for P1 incidents.', d:1 },
{ q:'In ITIL terms, an “incident” is…', o:['A planned upgrade','An unplanned interruption or reduction in quality of a service','A project meeting','A new feature request'], a:1, w:'Incidents restore service fast; problems find causes; changes alter things in a controlled way.', d:1 },
{ q:'A P1 (Priority 1) incident typically means…', o:['A minor cosmetic issue','A critical service is down or severely degraded for many users — immediate, all-hands response','A request for information','A routine password reset'], a:1, w:'P1 = business-critical impact: fastest response/resolution targets and management visibility.', d:1 },
{ q:'The difference between incident management and problem management is…', o:['There is none','Incidents restore service; problems investigate and remove the underlying root cause','Problems are for customers only','Incidents are scheduled'], a:1, w:'You can resolve 100 incidents and still need problem management to stop the 101st.', d:2 },
{ q:'Service transition is the phase that…', o:['Designs marketing for a service','Moves a new or changed service from build/project into stable live operation','Handles payroll','Retires all services'], a:1, w:'Transition covers release, deployment, knowledge transfer, readiness and early-life support — where go-lives succeed or fail.', d:1 },
{ q:'“KT” in a transition plan means…', o:['Known Ticket','Knowledge Transfer — structured handover of know-how from the outgoing to the incoming team','Key Transaction','Keyboard Testing'], a:1, w:'Documented, shadowed and reverse-shadowed KT is what makes a handover real rather than ceremonial.', d:2 },
{ q:'A CAB (Change Advisory Board) exists to…', o:['Approve annual leave','Assess and authorise significant changes, weighing risk, impact and timing','Design the service','Audit salaries'], a:1, w:'The CAB protects live services from unassessed change — risk review before, not apologies after.', d:2 },
{ q:'RCA stands for…', o:['Rapid Change Approval','Root Cause Analysis','Remote Call Audit','Resource Cost Allocation'], a:1, w:'Root cause analysis digs past symptoms (“server restarted”) to causes (“memory leak in release 4.2”).', d:1 },
{ q:'During a major incident, the incident manager’s communication should be…', o:['Silent until everything is fixed','Regular, factual updates at an agreed cadence — impact, actions, next update time — even when the update is “still working on it”','Full of technical jargon for end users','Sent only to the CEO'], a:1, w:'Cadence beats perfection: stakeholders forgive outages faster than silence.', d:2 },
{ s:'The same payroll interface fails on the last day of every month, raising an incident each time.', q:'Beyond fixing this month’s failure, the correct STOM action is to…', o:['Add a calendar reminder to watch it','Raise a problem record to find and eliminate the recurring root cause','Blame the payroll team','Close each incident faster'], a:1, w:'A pattern of related incidents is the textbook trigger for problem management.', d:2 },
{ q:'“Hypercare” after a go-live means…', o:['Extra marketing','A defined period of heightened support, monitoring and rapid response immediately after launch','Permanent 24×7 staffing','A discount period'], a:1, w:'Early-life support catches transition issues while the project team is still assembled to fix them.', d:2 },
{ q:'A runbook is…', o:['A training manual for marathons','Step-by-step documented procedures for known operational situations, so any trained engineer can execute them','A list of servers','A finance ledger'], a:1, w:'Runbooks turn individual heroics into reliable operations.', d:1 },
{ q:'A service catalogue describes…', o:['Staff birthdays','The services offered to the business, with scope, contacts and how to request them','Server prices','Competitors’ products'], a:1, w:'The catalogue is the business-facing menu of live and pipeline services.', d:2 },
{ q:'A risk register in transition planning is used to…', o:['Record who is on leave','Identify, assess and track risks to the transition with owners and mitigations','Store passwords','List servers only'], a:1, w:'Named risks with owners and mitigations are manageable; unnamed risks are surprises.', d:2 },
{ s:'Go-live is Friday. Testing is incomplete, two critical defects are open, and the business sponsor is pushing to launch anyway.', q:'The transition lead’s job is to…', o:['Launch silently and hope','Present a clear readiness assessment — what is untested, what could fail, the rollback plan — and record the decision and its owner','Refuse any involvement','Reduce the defect severities so the report looks green'], a:1, w:'Go/no-go decisions can accept risk — but knowingly, in writing, with mitigations and rollback ready.', d:3 },
{ q:'KPI vs SLA — which is right?', o:['They are identical','An SLA is the contractual commitment; KPIs are the measures that show whether it (and the service) is performing','KPIs are legal contracts','SLAs measure staff happiness'], a:1, w:'KPIs (e.g. % incidents resolved within target) evidence SLA performance.', d:2 },
{ q:'Escalation in incident handling means…', o:['Shouting','Moving an issue to a higher level of expertise or authority when it cannot be resolved at the current level or within target time','Closing the ticket','Deleting logs'], a:1, w:'Functional escalation brings deeper skill; hierarchical escalation brings decision authority. Both are normal, not failures.', d:1 },
{ q:'Knowledge articles and documentation matter most in operations because they…', o:['Look good in audits only','Make service quality independent of any one person’s memory or availability','Increase ticket counts','Replace training'], a:1, w:'Documented knowledge survives shift changes, holidays and attrition — the core of transition thinking.', d:2 },
{ s:'A key engineer who alone understands a critical system resigns with two weeks’ notice.', q:'The immediate transition priority is…', o:['Panic','Structured knowledge capture — documented procedures, shadowing/reverse-shadowing sessions, and access/credential handover — before the last day','Hire first, document later','Ask them to stay reachable forever'], a:1, w:'Single points of knowledge are operational risks; the notice period is a KT sprint.', d:3 },
{ q:'In a service review meeting, the most valuable thing an operations lead brings is…', o:['Excuses','Trends and insights — what the incidents and SLA data say, what is being done about the top patterns','A list of who raised tickets','New tool demos'], a:1, w:'Reviews exist to convert operational data into improvement decisions.', d:3 }
];

BANKS['data-analyst'] = [
{ q:'In Excel, XLOOKUP/VLOOKUP is used to…', o:['Sort a table','Fetch a matching value from another table or range by a key','Count cells','Format charts'], a:1, w:'Lookup functions join data the spreadsheet way — e.g. bring product prices into an orders sheet by product ID.', d:1 },
{ q:'Why would an analyst prefer the median over the average for salaries?', o:['It is easier to spell','Salaries are skewed by a few very high values; the median shows the typical middle value honestly','The average is illegal','Medians are always larger'], a:1, w:'Averages are dragged by outliers (one CEO salary lifts the “average”); the median resists them.', d:1 },
{ q:'For showing a trend over 12 months, the default chart choice is a…', o:['Pie chart','Line chart','Scatter plot of categories','Table of raw numbers only'], a:1, w:'Lines make direction and turning points over time immediately visible.', d:1 },
{ q:'The SQL WHERE clause…', o:['Sorts results','Filters rows before they are returned','Creates tables',' renames columns'], a:1, w:'WHERE decides which rows survive into the result set.', d:1 },
{ q:'Before analysing a new dataset, the first professional step is to…', o:['Build a dashboard','Profile the data — check for missing values, duplicates, wrong types and impossible values','Share it widely','Delete outliers'], a:1, w:'Cleaning and understanding come before conclusions; most analysis errors are data errors.', d:1 },
{ q:'Duplicate rows in a report most commonly cause…', o:['Faster queries','Inflated totals and counts','Better charts','Nothing at all'], a:1, w:'Duplicates silently double-count — deduplication and key checks are analyst basics.', d:2 },
{ s:'Your dashboard shows sales fell 60% in March.', q:'Before reporting a crisis, you should first…', o:['Email the CEO','Verify the data — completeness of March data, changed definitions, pipeline or extraction issues','Redesign the chart','Compare with a competitor'], a:1, w:'Most “shocking” results are data problems, not business events. Verify, then report.', d:2 },
{ q:'An A/B test is…', o:['Testing two spreadsheets','Randomly showing two variants to comparable groups and comparing a measured outcome','A backup method','Alphabetical testing'], a:1, w:'Randomisation makes the groups comparable, so outcome differences can be attributed to the variant.', d:2 },
{ q:'Power BI’s advantage over a static Excel report is that…', o:['It has nicer colours','Reports connect to data sources and refresh interactively — filters and drill-downs update every visual','It needs no data','It replaces analysts'], a:1, w:'Live, interactive, refreshable reporting is the step up from emailed static files.', d:1 },
{ q:'“Percentage change” from 200 to 250 is…', o:['50%','25%','20%','125%'], a:1, w:'(250 − 200) / 200 = 25%. The base is the starting value.', d:1 },
{ s:'Two managers give you conflicting definitions of “active user” for the same report.', q:'The analyst’s correct move is to…', o:['Pick the definition from the senior manager silently','Surface the conflict, get one agreed definition documented, and label the report with it','Deliver two different reports','Use last quarter’s definition without asking'], a:1, w:'Definition conflicts are resolved explicitly and documented — quiet choices create dueling numbers.', d:2 },
{ q:'Conditional formatting in Excel is best used to…', o:['Make sheets colourful','Visually flag values that meet rules — e.g. targets missed — so patterns are spotted instantly','Hide data','Print faster'], a:1, w:'Formatting should direct attention to meaning, not decoration.', d:1 },
{ q:'Data storytelling means…', o:['Inventing exciting numbers','Structuring analysis as a narrative — context, the key finding, evidence, and the recommended action','Only using stories instead of charts','Reading reports aloud'], a:1, w:'Decision-makers remember a clear storyline anchored in honest evidence, not a chart dump.', d:2 },
{ q:'A stakeholder asks for “a report on everything, urgently”. The analyst should first ask…', o:['Nothing — start immediately','What decision it feeds, which metrics matter, and what “urgent” means in time','For a week’s extension','Which software to buy'], a:1, w:'Clarifying the decision and scope prevents the classic fate of urgent everything-reports: being read by no one.', d:2 },
{ q:'Cleaning a column of dates stored as mixed text formats is needed because…', o:['Text looks untidy','Sorting, filtering and calculations silently fail or misorder when dates are inconsistent text','Excel demands it','Dates expire'], a:1, w:'Type consistency is what makes data computable; mixed formats are a top source of silent errors.', d:2 },
{ q:'“Outlier” values should be…', o:['Always deleted','Investigated — they may be errors to fix or the most important signal in the data','Always kept without checking','Reported to HR'], a:1, w:'An outlier can be a typo (₹10,00,000 instead of ₹1,00,000) or a fraud signal — both deserve a look, not a reflex.', d:3 },
{ q:'The main purpose of a dashboard’s filters/slicers is to let viewers…', o:['Decorate the page','Explore the same data by segment — region, month, product — without rebuilding the report','Export to PDF only','Slow the report down'], a:1, w:'Interactivity turns one report into many views while keeping definitions consistent.', d:1 },
{ s:'Your analysis shows a marketing campaign “doubled conversions”, but the campaign ran during a festival sale week.', q:'The careful conclusion is…', o:['The campaign definitely caused the doubling','The increase coincides with both the campaign and the festival — without a comparison group or baseline, causation is unproven','Festivals do not affect sales','Conversions do not matter'], a:1, w:'Confounding events are the classic analytics trap; honest analysts flag them instead of claiming credit for the data.', d:3 },
{ q:'In an interview, you are handed a small table and asked what you notice. A strong answer…', o:['Recites the numbers','States the headline pattern, one supporting detail, one caveat or question, and a sensible next step','Says the data is insufficient for anything','Asks for the answer key'], a:1, w:'Pattern → evidence → caveat → next step is the analyst’s thinking made audible.', d:3 },
{ q:'Reproducibility in analysis means…', o:['Typing fast','Someone else following your steps (or your script) reaches the same result from the same data','Using the same laptop','Printing the report twice'], a:1, w:'Documented steps and queries make work checkable — the difference between analysis and opinion.', d:2 }
];
